/* ÜRETİLMİŞ — elle düzenleme (R-65). Kaynak: brand/<id>/tokens/ */
:root {
  --comp-status-bar-bg: var(--role-surface);
  --comp-status-bar-text: var(--role-text-muted);
  --comp-tolerance-limit: var(--role-state-warn);
  --comp-tolerance-out: var(--role-state-error);
  --comp-tolerance-track: var(--role-line-hair);
  --ramp-gray-100: oklch(0.93 0.004 250);
  --ramp-gray-200: oklch(0.84 0.006 250);
  --ramp-gray-300: oklch(0.76 0.006 250);
  --ramp-gray-50: oklch(0.97 0.004 250);
  --ramp-gray-500: oklch(0.58 0.008 250);
  --ramp-gray-800: oklch(0.28 0.010 250);
  --ramp-gray-900: oklch(0.21 0.010 250);
  --ramp-gray-950: oklch(0.16 0.010 250);
  --ramp-signal-danger: oklch(0.58 0.160 25);
  --ramp-signal-ok: oklch(0.65 0.120 150);
  --ramp-signal-warn: oklch(0.72 0.150 75);
  --role-bg: var(--ramp-gray-950);
  --role-line-hair: var(--ramp-gray-800);
  --role-state-error: var(--ramp-signal-danger);
  --role-state-ok: var(--ramp-signal-ok);
  --role-state-warn: var(--ramp-signal-warn);
  --role-surface: var(--ramp-gray-900);
  --role-text: var(--ramp-gray-50);
  --role-text-muted: var(--ramp-gray-500);
}

[data-surface='console'] {
  --role-bg: var(--ramp-gray-950);
  --role-line-hair: var(--ramp-gray-800);
  --role-state-error: var(--ramp-signal-danger);
  --role-state-ok: var(--ramp-signal-ok);
  --role-state-warn: var(--ramp-signal-warn);
  --role-surface: var(--ramp-gray-900);
  --role-text: var(--ramp-gray-50);
  --role-text-muted: var(--ramp-gray-500);
}

[data-surface='studio'] {
  --role-bg: var(--ramp-gray-300);
  --role-line-hair: var(--ramp-gray-200);
  --role-state-error: var(--ramp-signal-danger);
  --role-state-ok: var(--ramp-signal-ok);
  --role-state-warn: var(--ramp-signal-warn);
  --role-surface: var(--ramp-gray-50);
  --role-text: var(--ramp-gray-950);
  --role-text-muted: var(--ramp-gray-500);
}
